import json, random, subprocess, sys, os, tempfile
sys.path.insert(0,'/workspace/tmp')
from ref import Ref
MAIN='/workspace/submission/main.py'

def run_stream(prog, requests):
    with tempfile.TemporaryDirectory() as d:
        p=os.path.join(d,'prog.json'); open(p,'w').write(json.dumps(prog))
        proc=subprocess.Popen([sys.executable,'-I',MAIN,'stream',p],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
        inp='\n'.join(json.dumps(r) for r in requests)+'\n'
        out,err=proc.communicate(inp)
        return out,err,proc.returncode

def gen_config(rng):
    W=rng.randint(1,6); nr=rng.randint(0,10); rules=[]; used=set(); total=0
    for _ in range(nr):
        rid=rng.randint(0,80)
        while rid in used: rid=rng.randint(0,100)
        used.add(rid)
        k=rng.randint(1,8)
        if total+k>16384: break
        total+=k
        ranges=[]
        for _ in range(k):
            lo=rng.randint(-6,6); hi=rng.randint(lo,6); ranges.append([lo,hi])
        rules.append({"id":rid,"class":rng.randint(0,3),"priority":rng.randint(-5,5),"ranges":ranges})
    def leaf(): return {"class":rng.randint(0,3)}
    def tree(depth):
        if depth>=4 or rng.random()<0.4: return leaf()
        return {"feature":rng.randint(0,W-1),"threshold":rng.randint(-4,4),"le":tree(depth+1),"gt":tree(depth+1)}
    return {"version":1,"idle_timeout":rng.choice([0,1,2,3,5,10]),"packet_limit":rng.randint(1,10),"prefix_width":W,"rules":rules,"fallback":tree(0)}

def gen_requests(rng, nflows_max=6, nreq=40):
    reqs=[]; openflows=[]; time=0
    for _ in range(nreq):
        op=rng.choice(['open','open','chunk','chunk','chunk','tick','close'])
        if op=='open':
            if len(openflows)>=nflows_max: op='tick'
            else:
                time+=rng.randint(0,2); fid=rng.randint(0,10)
                if fid in openflows: op='tick'
                else:
                    reqs.append({"op":"open","flow":fid,"time":time}); openflows.append(fid); continue
        if op=='tick':
            time+=rng.randint(0,4); reqs.append({"op":"tick","time":time})
        elif op=='chunk':
            npk=rng.randint(0,6); packets=[]
            if openflows:
                for _ in range(npk):
                    time+=rng.randint(0,2); fid=rng.choice(openflows)
                    packets.append({"flow":fid,"time":time,"source":rng.randint(0,1),"length":rng.randint(1,8)})
            reqs.append({"op":"chunk","packets":packets})
        elif op=='close':
            if not openflows:
                time+=rng.randint(0,3); reqs.append({"op":"tick","time":time})
            else:
                fid=rng.choice(openflows); time+=rng.randint(0,2)
                reqs.append({"op":"close","flow":fid,"time":time}); openflows.remove(fid)
    for fid in list(openflows):
        time+=rng.randint(0,2); reqs.append({"op":"close","flow":fid,"time":time})
    return reqs

def ref_responses(cfg,reqs):
    r=Ref(cfg); outs=[]
    for q in reqs:
        try: outs.append(r.handle(q))
        except ValueError: outs.append({"error":"event"}); break
    return outs

def compile_cfg(cfg):
    return subprocess.run([sys.executable,'-I',MAIN,'compile'],input=json.dumps(cfg),stdout=subprocess.PIPE,text=True)

def main():
    rng=random.Random(int(sys.argv[1])); N=int(sys.argv[2])
    for it in range(N):
        cfg=gen_config(rng); cp=compile_cfg(cfg)
        assert cp.returncode==0, (cp.stdout,cfg)
        prog=json.loads(cp.stdout); reqs=gen_requests(rng)
        out,err,rc=run_stream(prog,reqs)
        if rc!=0: print("FAIL rc",it,err[:300]); print(json.dumps(cfg)); print(json.dumps(reqs)); return
        got=[json.loads(x) for x in out.strip().split('\n') if x.strip()]
        exp=ref_responses(cfg,reqs)
        if got!=exp:
            print("MISMATCH",it); print("CFG",json.dumps(cfg)); print("REQS",json.dumps(reqs))
            for i,(g,e) in enumerate(zip(got,exp)):
                if g!=e: print("resp",i,"got",json.dumps(g),"exp",json.dumps(e)); break
            if len(got)!=len(exp): print("len",len(got),len(exp))
            return
    print("ALL OK",N)
main()
